document.getElementById('commentForm').addEventListener('submit',function(e){e.preventDefault();let formData=new FormData(this);fetch('/send_comment/',{method:'POST',body:formData,}).then(response=>response.json()).then(data=>{document.getElementById('responseMessage').textContent='Your comment has been sent. Thank you for your feedback!';document.getElementById('responseMessage').style.display='block';document.getElementById('commentForm').reset();}).catch(error=>{document.getElementById('responseMessage').textContent='Something went wrong. Please try again later.';document.getElementById('responseMessage').style.display='block';});});;